```json
{
  "root_causes": [
    {
      "service": "payment",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) n FROM normal_traces WHERE service_name = 'payment' GROUP BY 1 UNION ALL SELECT 'abnormal', count(*) FROM abnormal_traces WHERE service_name = 'payment'",
          "claim": "Payment emitted 32 spans in the normal period and zero spans in the entire abnormal window."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_pod_name, min(value) vmin, max(value) vmax FROM abnormal_metrics WHERE metric = 'k8s.container.restarts' AND attr_k8s_pod_name LIKE 'payment%' GROUP BY ALL",
          "claim": "Payment pod restart counter rose from 0 to 1 at the abnormal start and stayed there; the pod was not replaced or recovered."
        },
        {
          "kind": "metric",
          "sql": "SELECT date_trunc('minute', time) m, round(avg(value),0) rss FROM abnormal_metrics WHERE service_name = 'payment' AND metric = 'container.memory.rss' GROUP BY 1 ORDER BY 1",
          "claim": "Payment memory dropped from about 102 MB to about 2.4 MB at the restart and stayed flat, consistent with no live process."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) n, avg(duration)/1e6 avg_ms FROM abnormal_traces WHERE span_name LIKE '%PaymentService/Charge%' GROUP BY 1,2",
          "claim": "Every checkout call to PaymentService/Charge failed in about 0.1 ms, i.e. refused immediately, 46 of 46 times."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "payment",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) n, avg(duration)/1e6 avg_ms FROM abnormal_traces WHERE service_name = 'checkout' AND span_name IN ('oteldemo.PaymentService/Charge','oteldemo.CheckoutService/PlaceOrder') GROUP BY 1,2",
          "claim": "Checkout's PlaceOrder server spans all returned Error (46 of 46) because the payment Charge calls failed."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name = 'frontend' AND span_name IN ('grpc.oteldemo.CheckoutService/PlaceOrder','POST /api/checkout') GROUP BY 1,2,3",
          "claim": "Frontend's gRPC PlaceOrder client calls and POST /api/checkout server spans returned Error and HTTP 500 in the abnormal window."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name = 'frontend-proxy' AND attr_status_code = 'Error' GROUP BY 1,2,3,4",
          "claim": "Frontend-proxy ingress returned HTTP 500 for 116 user requests in the abnormal window, against 18 in normal."
        }
      ]
    }
  ]
}
```

